import { FullAssessmentItem, AssessmentScoringResult } from "./assessment-types";

const DEFAULT_OPTIONS = ["Not at all (0)", "Rarely / Mildly (1)", "Frequently / Moderately (2)", "Consistently / Markedly (3)"];

function standardScoring(scores: number[]): AssessmentScoringResult {
  const sum = scores.reduce((a, b) => a + (b > -1 ? b : 0), 0);
  const maxScore = scores.length * 3;
  const pct = maxScore > 0 ? (sum / maxScore) * 100 : 0;
  let level = "Balanced / Mild Indicator";
  let badge = "bg-emerald-100 text-emerald-800";
  if (pct > 66) {
    level = "Marked Indicator / Deep Focus";
    badge = "bg-red-100 text-red-800";
  } else if (pct > 33) {
    level = "Moderate Reflective Indicator";
    badge = "bg-amber-100 text-amber-800";
  }
  return { score: sum, maxScore, level, badge };
}

